const Database = require('better-sqlite3');
const path = require('path');
const bcrypt = require('bcryptjs');

const dbPath = process.env.DATABASE_PATH || './database.sqlite';
const db = new Database(dbPath);

// Habilitar foreign keys
db.pragma('foreign_keys = ON');

// Criar tabelas
db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    email TEXT UNIQUE NOT NULL,
    password TEXT NOT NULL,
    is_admin INTEGER DEFAULT 0,
    is_suspended INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );

  CREATE TABLE IF NOT EXISTS services (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    title TEXT NOT NULL,
    description TEXT NOT NULL,
    price REAL NOT NULL,
    category TEXT NOT NULL,
    status TEXT DEFAULT 'pending' CHECK(status IN ('pending', 'approved', 'rejected')),
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
  );

  CREATE TABLE IF NOT EXISTS contracts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    service_id INTEGER NOT NULL,
    client_id INTEGER NOT NULL,
    provider_id INTEGER NOT NULL,
    status TEXT DEFAULT 'active' CHECK(status IN ('active', 'completed', 'cancelled')),
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (service_id) REFERENCES services(id) ON DELETE CASCADE,
    FOREIGN KEY (client_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (provider_id) REFERENCES users(id) ON DELETE CASCADE
  );

  CREATE INDEX IF NOT EXISTS idx_services_user ON services(user_id);
  CREATE INDEX IF NOT EXISTS idx_services_status ON services(status);
  CREATE INDEX IF NOT EXISTS idx_contracts_client ON contracts(client_id);
  CREATE INDEX IF NOT EXISTS idx_contracts_provider ON contracts(provider_id);
`);

// Criar admin padrão se não existir
const adminExists = db.prepare('SELECT id FROM users WHERE email = ?').get('admin@freelancehub.com');
if (!adminExists) {
  const hashedPassword = bcrypt.hashSync('admin123', 10);
  db.prepare(`
    INSERT INTO users (name, email, password, is_admin)
    VALUES (?, ?, ?, 1)
  `).run('Administrador', 'admin@freelancehub.com', hashedPassword);
  console.log('✓ Conta admin criada: admin@freelancehub.com / admin123');
}

module.exports = db;

=== middleware/auth.js ===
function requireAuth(req, res, next) {
  if (!req.session.userId) {
    return res.status(401).json({ error: 'Não autenticado' });
  }
  next();
}

function requireAdmin(req, res, next) {
  if (!req.session.userId || !req.session.isAdmin) {
    return res.status(403).json({ error: 'Acesso negado' });
  }
  next();
}

module.exports = { requireAuth, requireAdmin };

=== routes/auth.js ===
const express = require('express');
const bcrypt = require('bcryptjs');
const { body, validationResult } = require('express-validator');
const db = require('../database');
const router = express.Router();

// Registro
router.post('/register',
  body('name').trim().isLength({ min: 2 }).escape(),
  body('email').isEmail().normalizeEmail(),
  body('password').isLength({ min: 6 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { name, email, password } = req.body;

    try {
      const hashedPassword = bcrypt.hashSync(password, 10);
      const result = db.prepare(
        'INSERT INTO users (name, email, password) VALUES (?, ?, ?)'
      ).run(name, email, hashedPassword);

      req.session.userId = result.lastInsertRowid;
      req.session.isAdmin = false;

      res.json({ 
        success: true, 
        user: { id: result.lastInsertRowid, name, email, isAdmin: false } 
      });
    } catch (error) {
      if (error.message.includes('UNIQUE')) {
        return res.status(400).json({ error: 'Email já cadastrado' });
      }
      res.status(500).json({ error: 'Erro ao criar conta' });
    }
  }
);

// Login
router.post('/login',
  body('email').isEmail().normalizeEmail(),
  body('password').exists(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { email, password } = req.body;

    const user = db.prepare('SELECT * FROM users WHERE email = ?').get(email);

    if (!user || !bcrypt.compareSync(password, user.password)) {
      return res.status(401).json({ error: 'Email ou senha incorretos' });
    }

    if (user.is_suspended) {
      return res.status(403).json({ error: 'Conta suspensa' });
    }

    req.session.userId = user.id;
    req.session.isAdmin = user.is_admin === 1;

    res.json({ 
      success: true, 
      user: { 
        id: user.id, 
        name: user.name, 
        email: user.email, 
        isAdmin: user.is_admin === 1 
      } 
    });
  }
);

// Logout
router.post('/logout', (req, res) => {
  req.session.destroy();
  res.json({ success: true });
});

// Verificar sessão
router.get('/me', (req, res) => {
  if (!req.session.userId) {
    return res.status(401).json({ error: 'Não autenticado' });
  }

  const user = db.prepare('SELECT id, name, email, is_admin FROM users WHERE id = ?')
    .get(req.session.userId);

  if (!user) {
    return res.status(404).json({ error: 'Usuário não encontrado' });
  }

  res.json({ 
    user: { 
      id: user.id, 
      name: user.name, 
      email: user.email, 
      isAdmin: user.is_admin === 1 
    } 
  });
});

module.exports = router;

=== routes/services.js ===
const express = require('express');
const { body, validationResult } = require('express-validator');
const db = require('../database');
const { requireAuth } = require('../middleware/auth');
const router = express.Router();

// Listar serviços aprovados (público)
router.get('/', (req, res) => {
  const services = db.prepare(`
    SELECT s.*, u.name as provider_name 
    FROM services s
    JOIN users u ON s.user_id = u.id
    WHERE s.status = 'approved'
    ORDER BY s.created_at DESC
  `).all();
  res.json(services);
});

// Meus serviços
router.get('/my', requireAuth, (req, res) => {
  const services = db.prepare(`
    SELECT s.*, u.name as provider_name 
    FROM services s
    JOIN users u ON s.user_id = u.id
    WHERE s.user_id = ?
    ORDER BY s.created_at DESC
  `).all(req.session.userId);
  res.json(services);
});

// Criar serviço
router.post('/', requireAuth,
  body('title').trim().isLength({ min: 5 }).escape(),
  body('description').trim().isLength({ min: 20 }).escape(),
  body('price').isFloat({ min: 0 }),
  body('category').trim().notEmpty().escape(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { title, description, price, category } = req.body;

    try {
      const result = db.prepare(`
        INSERT INTO services (user_id, title, description, price, category)
        VALUES (?, ?, ?, ?, ?)
      `).run(req.session.userId, title, description, price, category);

      res.json({ success: true, id: result.lastInsertRowid });
    } catch (error) {
      res.status(500).json({ error: 'Erro ao criar serviço' });
    }
  }
);

// Contratar serviço
router.post('/:id/hire', requireAuth, (req, res) => {
  const serviceId = req.params.id;

  const service = db.prepare('SELECT * FROM services WHERE id = ?').get(serviceId);

  if (!service) {
    return res.status(404).json({ error: 'Serviço não encontrado' });
  }

  if (service.status !== 'approved') {
    return res.status(400).json({ error: 'Serviço não disponível' });
  }

  if (service.user_id === req.session.userId) {
    return res.status(400).json({ error: 'Você não pode contratar seu próprio serviço' });
  }

  try {
    const result = db.prepare(`
      INSERT INTO contracts (service_id, client_id, provider_id)
      VALUES (?, ?, ?)
    `).run(serviceId, req.session.userId, service.user_id);

    res.json({ success: true, id: result.lastInsertRowid });
  } catch (error) {
    res.status(500).json({ error: 'Erro ao contratar serviço' });
  }
});

// Deletar serviço (apenas dono)
router.delete('/:id', requireAuth, (req, res) => {
  const service = db.prepare('SELECT * FROM services WHERE id = ?').get(req.params.id);

  if (!service) {
    return res.status(404).json({ error: 'Serviço não encontrado' });
  }

  if (service.user_id !== req.session.userId) {
    return res.status(403).json({ error: 'Sem permissão' });
  }

  db.prepare('DELETE FROM services WHERE id = ?').run(req.params.id);
  res.json({ success: true });
});

module.exports = router;

=== routes/contracts.js ===
const express = require('express');
const db = require('../database');
const { requireAuth } = require('../middleware/auth');
const router = express.Router();

// Meus contratos (como cliente ou fornecedor)
router.get('/my', requireAuth, (req, res) => {
  const contracts = db.prepare(`
    SELECT 
      c.*,
      s.title as service_title,
      s.price,
      s.category,
      client.name as client_name,
      provider.name as provider_name
    FROM contracts c
    JOIN services s ON c.service_id = s.id
    JOIN users client ON c.client_id = client.id
    JOIN users provider ON c.provider_id = provider.id
    WHERE c.client_id = ? OR c.provider_id = ?
    ORDER BY c.created_at DESC
  `).all(req.session.userId, req.session.userId);

  res.json(contracts);
});

// Atualizar status do contrato
router.patch('/:id', requireAuth, (req, res) => {
  const { status } = req.body;
  const contractId = req.params.id;

  if (!['active', 'completed', 'cancelled'].includes(status)) {
    return res.status(400).json({ error: 'Status inválido' });
  }

  const contract = db.prepare('SELECT * FROM contracts WHERE id = ?').get(contractId);

  if (!contract) {
    return res.status(404).json({ error: 'Contrato não encontrado' });
  }

  if (contract.client_id !== req.session.userId && contract.provider_id !== req.session.userId) {
    return res.status(403).json({ error: 'Sem permissão' });
  }

  db.prepare('UPDATE contracts SET status = ? WHERE id = ?').run(status, contractId);
  res.json({ success: true });
});

module.exports = router;

=== routes/admin.js ===
const express = require('express');
const db = require('../database');
const { requireAdmin } = require('../middleware/auth');
const router = express.Router();

// Todos os serviços
router.get('/services', requireAdmin, (req, res) => {
  const services = db.prepare(`
    SELECT s.*, u.name as provider_name, u.email as provider_email
    FROM services s
    JOIN users u ON s.user_id = u.id
    ORDER BY s.created_at DESC
  `).all();
  res.json(services);
});

// Aprovar serviço
router.patch('/services/:id/approve', requireAdmin, (req, res) => {
  db.prepare('UPDATE services SET status = ? WHERE id = ?').run('approved', req.params.id);
  res.json({ success: true });
});

// Rejeitar serviço
router.patch('/services/:id/reject', requireAdmin, (req, res) => {
  db.prepare('UPDATE services SET status = ? WHERE id = ?').run('rejected', req.params.id);
  res.json({ success: true });
});

// Deletar serviço
router.delete('/services/:id', requireAdmin, (req, res) => {
  db.prepare('DELETE FROM services WHERE id = ?').run(req.params.id);
  res.json({ success: true });
});

// Todos os usuários
router.get('/users', requireAdmin, (req, res) => {
  const users = db.prepare(`
    SELECT id, name, email, is_admin, is_suspended, created_at
    FROM users
    ORDER BY created_at DESC
  `).all();
  res.json(users);
});

// Suspender/reativar usuário
router.patch('/users/:id/toggle-suspend', requireAdmin, (req, res) => {
  const user = db.prepare('SELECT is_suspended FROM users WHERE id = ?').get(req.params.id);

  if (!user) {
    return res.status(404).json({ error: 'Usuário não encontrado' });
  }

  const newStatus = user.is_suspended === 1 ? 0 : 1;
  db.prepare('UPDATE users SET is_suspended = ? WHERE id = ?').run(newStatus, req.params.id);

  res.json({ success: true, suspended: newStatus === 1 });
});

// Todos os contratos
router.get('/contracts', requireAdmin, (req, res) => {
  const contracts = db.prepare(`
    SELECT 
      c.*,
      s.title as service_title,
      s.price,
      client.name as client_name,
      client.email as client_email,
      provider.name as provider_name,
      provider.email as provider_email
    FROM contracts c
    JOIN services s ON c.service_id = s.id
    JOIN users client ON c.client_id = client.id
    JOIN users provider ON c.provider_id = provider.id
    ORDER BY c.created_at DESC
  `).all();
  res.json(contracts);
});

module.exports = router;

